import type {Day, DetailLayout, Feature, L10n, Pricing, Stay, Step, TourDetails, TourRecord, Tier} from "@/types/tour-catalog";

const l = (en: string, es: string, pt: string): L10n => ({en, es, pt});
const tiers: Tier[] = ["economic", "standard", "premium"];
const stay = (nights: number[], name: L10n, type: L10n, board: L10n): Stay => ({nights, name, type, board});
const mockCircuitStays = (count: number, name: L10n): Record<Tier, Stay[]> => Object.fromEntries(tiers.map((tier) => [tier, Array.from({length: count}, (_, index) => stay([index + 1], name, l("To be confirmed", "Por confirmar", "Por confirmar"), l("To be confirmed", "Por confirmar", "Por confirmar")))])) as Record<Tier, Stay[]>;
const feature = (id: string, label: L10n, economic: boolean | L10n, standard: boolean | L10n = economic, premium: boolean | L10n = standard): Feature => ({id, label, tiers: {economic, standard, premium}});
const offers = (unit: "person" | "vehicle" | "group", prices: Record<Tier, number>, features: Feature[], summaries: Record<Tier, L10n>): Pricing => ({kind: "offers", unit, tiers: prices, features, tierSummary: summaries});
const step = (time: string | undefined, enTitle: string, esTitle: string, ptTitle: string, enText: string, esText: string, ptText: string, onlyTiers?: Tier[]): Step => ({...(time ? {time} : {}), title: l(enTitle, esTitle, ptTitle), text: l(enText, esText, ptText), ...(onlyTiers ? {onlyTiers} : {})});
const day = (num: number, title: L10n, from: L10n, to: L10n, text: L10n, highlights: L10n[], overnight?: L10n, meals?: Day["meals"]): Day => ({day: num, title, from, to, text, highlights, ...(overnight ? {overnight} : {}), ...(meals?.length ? {meals} : {})});

const standardFaqs = [
  {q: l("What should I know before booking?", "¿Qué debo saber antes de reservar?", "O que devo saber antes de reservar?"), a: l("Review the itinerary, included services and meeting details on this page. Our team confirms the final arrangements after you send a request.", "Revisa el itinerario, los servicios incluidos y el punto de encuentro en esta página. Nuestro equipo confirma los detalles finales después de recibir tu solicitud.", "Consulte o itinerário, os serviços incluídos e o ponto de encontro nesta página. A nossa equipa confirma os detalhes finais depois de receber o seu pedido.")},
  {q: l("How do I confirm my place?", "¿Cómo confirmo mi plaza?", "Como confirmo o meu lugar?"), a: l("Send a booking request with your preferred date. Our team will contact you to confirm availability and the final price.", "Envía una solicitud con la fecha que prefieras. Nuestro equipo se pondrá en contacto contigo para confirmar la disponibilidad y el precio final.", "Envie um pedido com a data da sua preferência. A nossa equipa entrará em contacto para confirmar a disponibilidade e o preço final.")},
];

function summaryDetails(layout: DetailLayout, summary: L10n, highlight: L10n, days?: Day[], extras: Pick<TourDetails, "places" | "leadTitle"> = {}): TourDetails {
  return {
    layout,
    ...extras,
    highlights: [highlight],
    overview: [summary],
    ...(days ? {days} : {steps: [step(undefined, "Experience details", "Detalles de la experiencia", "Detalhes da experiência", "The exact sequence is confirmed with your booking request.", "El orden exacto se confirma con tu solicitud de reserva.", "A sequência exata é confirmada com o seu pedido de reserva.")]}),
    included: [], notIncluded: [], faqs: standardFaqs,
  };
}

const desertFeature = (id: string, label: L10n, e: boolean | L10n, s: boolean | L10n = e, p: boolean | L10n = e) => feature(id, label, e, s, p);

